{"content": "/* ============================================================
   CN Codex 企业官网 — 主样式表
   主题：深色炫酷科技风 | 品牌色：靛蓝→紫色渐变
   ============================================================ */

/* ---- CSS 变量 ---- */
:root {
    --primary: #6366F1;
    --primary-light: #818CF8;
    --secondary: #8B5CF6;
    --accent: #06B6D4;
    --gold: #F59E0B;
    --bg-dark: #0A0A0F;
    --bg-card: #1A1A2E;
    --bg-secondary: #12121A;
    --text-primary: #FFFFFF;
    --text-secondary: #94A3B8;
    --text-muted: #64748B;
    --border: rgba(99, 102, 241, 0.2);
    --border-hover: rgba(99, 102, 241, 0.5);

    --gradient-hero: linear-gradient(135deg, #6366F1 0%, #8B5CF6 50%, #06B6D4 100%);
    --gradient-btn: linear-gradient(90deg, #6366F1, #8B5CF6);
    --gradient-card: linear-gradient(135deg, rgba(99,102,241,0.08), rgba(6,182,212,0.08));
    --gradient-glass: linear-gradient(135deg, rgba(255,255,255,0.05), rgba(255,255,255,0.02));

    --font: 'Inter', system-ui, -apple-system, sans-serif;

    --nav-height: 70px;
    --max-width: 1200px;
    --radius: 16px;
    --radius-sm: 8px;
    --radius-lg: 24px;

    --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* ---- Reset & Base ---- */
*, *::before, *::after {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
    scroll-padding-top: var(--nav-height);
}

body {
    font-family: var(--font);
    background: var(--bg-dark);
    color: var(--text-primary);
    line-height: 1.6;
    overflow-x: hidden;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

a {
    color: inherit;
    text-decoration: none;
}

ul { list-style: none; }

img { max-width: 100%; display: block; }

/* ---- Scrollbar ---- */
::-webkit-scrollbar { width: 8px; }
::-webkit-scrollbar-track { background: var(--bg-dark); }
::-webkit-scrollbar-thumb {
    background: linear-gradient(var(--primary), var(--secondary));
    border-radius: 4px;
}

/* ---- Selection ---- */
::selection {
    background: rgba(99, 102, 241, 0.4);
    color: white;
}

/* ============================================================
   导航栏
   ============================================================ */
.navbar {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    height: var(--nav-height);
    z-index: 1000;
    transition: all var(--transition);
}

.navbar.scrolled {
    background: rgba(10, 10, 15, 0.85);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border-bottom: 1px solid var(--border);
}

.navbar-container {
    max-width: var(--max-width);
    margin: 0 auto;
    padding: 0 24px;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.navbar-logo {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 1.25rem;
    font-weight: 700;
    letter-spacing: -0.5px;
}

.logo-text {
    background: var(--gradient-hero);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.nav-links {
    display: flex;
    align-items: center;
    gap: 32px;
}

.nav-link {
    position: relative;
    font-size: 0.9375rem;
    font-weight: 500;
    color: var(--text-secondary);
    transition: color var(--transition);
    padding: 4px 0;
}

.nav-link::after {
    content: '';
    position: absolute;
    bottom: -2px;
    left: 0;
    width: 0;
    height: 2px;
    background: var(--gradient-hero);
    transition: width var(--transition);
    border-radius: 1px;
}

.nav-link:hover,
.nav-link.active {
    color: var(--text-primary);
}

.nav-link:hover::after,
.nav-link.active::after {
    width: 100%;
}

/* ---- Nav Toggle (Mobile) ---- */
.nav-toggle {
    display: none;
    flex-direction: column;
    gap: 5px;
    background: none;
    border: none;
    cursor: pointer;
    padding: 8px;
}

.nav-toggle span {
    display: block;
    width: 24px;
    height: 2px;
    background: var(--text-primary);
    border-radius: 2px;
    transition: all var(--transition);
}

.nav-toggle.open span:nth-child(1) {
    transform: translateY(7px) rotate(45deg);
}

.nav-toggle.open span:nth-child(2) {
    opacity: 0;
}

.nav-toggle.open span:nth-child(3) {
    transform: translateY(-7px) rotate(-45deg);
}

/* ============================================================
   Hero 首屏
   ============================================================ */
.hero {
    position: relative;
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
}

#particleCanvas {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: 0;
}

.hero-overlay {
    position: absolute;
    inset: 0;
    background: radial-gradient(ellipse at center, transparent 0%, var(--bg-dark) 70%);
    z-index: 1;
}

.hero-content {
    position: relative;
    z-index: 2;
    max-width: var(--max-width);
    padding: 0 24px;
    text-align: center;
}

.hero-badge {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 8px 20px;
    border-radius: 100px;
    background: rgba(99, 102, 241, 0.1);
    border: 1px solid rgba(99, 102, 241, 0.2);
    font-size: 0.875rem;
    color: var(--text-secondary);
    margin-bottom: 32px;
}

.badge-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #22C55E;
    animation: pulse-dot 2s ease-in-out infinite;
}

@keyframes pulse-dot {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.4; }
}

.hero-title {
    margin-bottom: 24px;
}

.hero-title-line {
    display: block;
    font-size: clamp(2.5rem, 6vw, 4.5rem);
    font-weight: 800;
    line-height: 1.1;
    letter-spacing: -2px;
}

.hero-title-line:first-child {
    margin-bottom: 8px;
}

.gradient-text {
    background: var(--gradient-hero);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.hero-subtitle {
    font-size: clamp(1rem, 2vw, 1.375rem);
    color: var(--text-secondary);
    max-width: 600px;
    margin: 0 auto 40px;
    line-height: 1.6;
}

.hero-actions {
    display: flex;
    gap: 16px;
    justify-content: center;
    margin-bottom: 80px;
    flex-wrap: wrap;
}

.btn {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 14px 32px;
    border-radius: 50px;
    font-size: 1rem;
    font-weight: 600;
    font-family: var(--font);
    cursor: pointer;
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
    border: none;
    position: relative;
    overflow: hidden;
}

.btn-primary {
    background: var(--gradient-btn);
    color: white;
    box-shadow: 0 4px 20px rgba(99, 102, 241, 0.3);
}

.btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 30px rgba(99, 102, 241, 0.5);
}

.btn-outline {
    background: transparent;
    color: var(--text-primary);
    border: 1px solid var(--border);
}

.btn-outline:hover {
    border-color: var(--primary);
    background: rgba(99, 102, 241, 0.1);
    transform: translateY(-2px);
}

/* ---- Hero Stats ---- */
.hero-stats {
    display: flex;
    justify-content: center;
    gap: 48px;
    flex-wrap: wrap;
}

.stat-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
}

.stat-number {
    font-size: 2.5rem;
    font-weight: 800;
    background: var(--gradient-hero);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.stat-suffix {
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--accent);
}

.stat-label {
    font-size: 0.875rem;
    color: var(--text-muted);
}

/* ---- Scroll Indicator ---- */
.scroll-indicator {
    position: absolute;
    bottom: 40px;
    left: 50%;
    transform: translateX(-50%);
    z-index: 2;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    color: var(--text-muted);
    font-size: 0.75rem;
    letter-spacing: 1px;
    text-transform: uppercase;
}

.scroll-arrow {
    width: 20px;
    height: 30px;
    border: 2px solid var(--text-muted);
    border-radius: 10px;
    position: relative;
}

.scroll-arrow::after {
    content: '';
    position: absolute;
    top: 6px;
    left: 50%;
    transform: translateX(-50%);
    width: 3px;
    height: 8px;
    background: var(--primary);
    border-radius: 2px;
    animation: scroll-bounce 2s ease-in-out infinite;
}

@keyframes scroll-bounce {
    0%, 100% { transform: translateX(-50%) translateY(0); opacity: 1; }
    50% { transform: translateX(-50%) translateY(8px); opacity: 0.3; }
}

/* ============================================================
   通用区块样式
   ============================================================ */
.section {
    padding: 120px 24px;
    max-width: var(--max-width);
    margin: 0 auto;
}

.section-header {
    text-align: center;
    margin-bottom: 80px;
}

.section-tag {
    display: inline-block;
    padding: 6px 16px;
    border-radius: 100px;
    background: rgba(99, 102, 241, 0.1);
    border: 1px solid rgba(99, 102, 241, 0.2);
    font-size: 0.8125rem;
    font-weight: 500;
    color: var(--primary-light);
    margin-bottom: 16px;
    letter-spacing: 1px;
    text-transform: uppercase;
}

.section-title {
    font-size: clamp(2rem, 4vw, 3rem);
    font-weight: 800;
    line-height: 1.2;
    letter-spacing: -1px;
    margin-bottom: 16px;
}

.section-desc {
    font-size: 1.125rem;
    color: var(--text-secondary);
    max-width: 500px;
    margin: 0 auto;
}

/* ============================================================
   功能区块
   ============================================================ */
.features {
    position: relative;
}

.features::before {
    content: '';
    position: absolute;
    top: 0;
    left: 50%;
    transform: translateX(-50%);
    width: 1px;
    height: 100%;
    background: linear-gradient(transparent, var(--border), transparent);
    opacity: 0.5;
}

.feature-block {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 80px;
    align-items: center;
    margin-bottom: 120px;
    position: relative;
}

.feature-block:last-child {
    margin-bottom: 0;
}

.feature-block.reverse {
    direction: rtl;
}

.feature-block.reverse .feature-content {
    direction: ltr;
}

.feature-visual {
    position: relative;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 300px;
}

/* ---- Code Window ---- */
.code-window {
    width: 100%;
    max-width: 440px;
    border-radius: var(--radius);
    overflow: hidden;
    background: #0D0D1A;
    border: 1px solid var(--border);
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5), 0 0 40px rgba(99, 102, 241, 0.1);
    transition: all var(--transition);
}

.code-window:hover {
    border-color: var(--border-hover);
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5), 0 0 60px rgba(99, 102, 241, 0.15);
}

.code-header {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 12px 16px;
    background: rgba(255, 255, 255, 0.03);
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}

.dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
}

.dot.red { background: #FF5F56; }
.dot.yellow { background: #FFBD2E; }
.dot.green { background: #27C93F; }

.code-title {
    margin-left: auto;
    font-size: 0.75rem;
    color: var(--text-muted);
    font-family: var(--font);
}

.code-body {
    padding: 20px;
    font-family: 'JetBrains Mono', 'Fira Code', monospace;
    font-size: 0.8125rem;
    line-height: 1.7;
    color: #E2E8F0;
    position: relative;
}

.code-body pre {
    font-family: inherit;
    white-space: pre;
}

.code-body .kw { color: #C084FC; }
.code-body .fn { color: #60A5FA; }
.code-body .num { color: #F59E0B; }
.code-body .comment { color: #6B7280; font-style: italic; }

.cursor-blink {
    animation: blink-cursor 1s step-end infinite;
    color: var(--primary);
    font-weight: 100;
}

@keyframes blink-cursor {
    0%, 100% { opacity: 1; }
    50% { opacity: 0; }
}

/* ---- Review Card ---- */
.review-card {
    width: 100%;
    max-width: 400px;
    border-radius: var(--radius);
    overflow: hidden;
    background: linear-gradient(135deg, #0D0D1A, #111128);
    border: 1px solid var(--border);
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
}

.review-header {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 16px 20px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}

.review-icon { font-size: 1.2rem; }

.review-title {
    font-weight: 600;
    font-size: 0.9375rem;
    flex: 1;
}

.review-score {
    font-size: 0.8125rem;
    font-weight: 600;
    color: #22C55E;
}

.review-body {
    padding: 16px 20px;
}

.issue {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 10px 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}

.issue:last-child { border-bottom: none; }

.issue-tag {
    padding: 2px 10px;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 600;
    min-width: 44px;
    text-align: center;
}

.issue.critical .issue-tag { background: rgba(239, 68, 68, 0.2); color: #EF4444; }
.issue.warning .issue-tag { background: rgba(245, 158, 11, 0.2); color: #F59E0B; }
.issue.info .issue-tag { background: rgba(59, 130, 246, 0.2); color: #60A5FA; }
.issue.pass .issue-tag { background: rgba(34, 197, 94, 0.2); color: #22C55E; }

.issue-text {
    font-size: 0.875rem;
    color: var(--text-secondary);
}

/* ---- Test Card ---- */
.test-card {
    width: 100%;
    max-width: 400px;
    padding: 24px;
    border-radius: var(--radius);
    background: linear-gradient(135deg, #0D0D1A, #111128);
    border: 1px solid var(--border);
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
}

.test-result {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 14px 16px;
    border-radius: var(--radius-sm);
    margin-bottom: 8px;
}

.test-result.success {
    background: rgba(34, 197, 94, 0.08);
}

.test-icon { font-size: 1.2rem; }

.test-info {
    display: flex;
    flex-direction: column;
}

.test-name {
    font-size: 0.875rem;
    font-weight: 600;
}

.test-status {
    font-size: 0.75rem;
    color: #22C55E;
}

.test-summary {
    margin-top: 16px;
    padding-top: 16px;
    border-top: 1px solid rgba(255, 255, 255, 0.05);
    text-align: center;
}

.summary-total {
    font-size: 0.9375rem;
    font-weight: 600;
    color: #22C55E;
}

/* ---- Doc Card ---- */
.doc-card {
    width: 100%;
    max-width: 400px;
    border-radius: var(--radius);
    overflow: hidden;
    background: linear-gradient(135deg, #0D0D1A, #111128);
    border: 1px solid var(--border);
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
}

.doc-header {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 16px 20px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
    font-size: 0.9375rem;
    font-weight: 600;
}

.doc-icon { font-size: 1.2rem; }

.doc-preview {
    padding: 16px 20px;
}

.doc-section {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 10px 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.03);
}

.doc-section:last-child { border-bottom: none; }

.doc-method {
    font-size: 0.6875rem;
    font-weight: 700;
    padding: 2px 8px;
    border-radius: 4px;
    min-width: 48px;
    text-align: center;
}

.doc-method.get { background: rgba(34, 197, 94, 0.15); color: #22C55E; }
.doc-method.post { background: rgba(59, 130, 246, 0.15); color: #60A5FA; }
.doc-method.put { background: rgba(245, 158, 11, 0.15); color: #F59E0B; }
.doc-method.delete { background: rgba(239, 68, 68, 0.15); color: #EF4444; }

.doc-section code {
    font-family: 'JetBrains Mono', 'Fira Code', monospace;
    font-size: 0.8125rem;
    color: var(--text-primary);
    flex: 1;
}

.doc-desc {
    font-size: 0.8125rem;
    color: var(--text-muted);
}

/* ---- Feature Content ---- */
.feature-content {
    padding: 20px;
}

.feature-icon {
    width: 56px;
    height: 56px;
    border-radius: 16px;
    background: var(--gradient-card);
    border: 1px solid var(--border);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.5rem;
    margin-bottom: 20px;
}

.feature-title {
    font-size: 1.625rem;
    font-weight: 700;
    margin-bottom: 12px;
    letter-spacing: -0.5px;
}

.feature-desc {
    font-size: 1rem;
    color: var(--text-secondary);
    line-height: 1.7;
    margin-bottom: 24px;
}

.feature-list {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.feature-list li {
    font-size: 0.9375rem;
    color: var(--text-secondary);
    display: flex;
    align-items: center;
    gap: 8px;
}

/* ============================================================
   核心特色 (Highlights)
   ============================================================ */
.highlights {
    position: relative;
}

.highlights::before {
    content: '';
    position: absolute;
    top: 0;
    left: -50vw;
    right: -50vw;
    height: 100%;
    background: radial-gradient(ellipse at center, rgba(99, 102, 241, 0.03) 0%, transparent 70%);
    pointer-events: none;
}

.highlights-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 24px;
}

.highlight-card {
    padding: 40px 32px;
    border-radius: var(--radius);
    background: var(--bg-card);
    border: 1px solid var(--border);
    transition: all var(--transition);
    position: relative;
    overflow: hidden;
}

.highlight-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: var(--gradient-hero);
    opacity: 0;
    transition: opacity var(--transition);
}

.highlight-card:hover {
    transform: translateY(-8px);
    border-color: var(--border-hover);
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.3), 0 0 30px rgba(99, 102, 241, 0.1);
}

.highlight-card:hover::before {
    opacity: 1;
}

.card-icon {
    width: 64px;
    height: 64px;
    border-radius: 16px;
    background: linear-gradient(135deg, color-mix(in srgb, var(--card-color) 15%, transparent), transparent);
    border: 1px solid color-mix(in srgb, var(--card-color) 30%, transparent);
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--card-color);
    margin-bottom: 20px;
    transition: all var(--transition);
}

.highlight-card:hover .card-icon {
    transform: scale(1.1);
    box-shadow: 0 0 30px color-mix(in srgb, var(--card-color) 30%, transparent);
}

.card-title {
    font-size: 1.25rem;
    font-weight: 700;
    margin-bottom: 12px;
}

.card-desc {
    font-size: 0.9375rem;
    color: var(--text-secondary);
    line-height: 1.7;
    margin-bottom: 20px;
}

.card-models {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
}

.card-models span {
    padding: 4px 12px;
    border-radius: 100px;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.06);
    font-size: 0.75rem;
    color: var(--text-muted);
}

/* ============================================================
   关于我们
   ============================================================ */
.about {
    max-width: 800px;
    text-align: center;
}

.about-text {
    text-align: left;
    margin-bottom: 48px;
}

.about-text p {
    font-size: 1.0625rem;
    color: var(--text-secondary);
    line-height: 1.8;
    margin-bottom: 20px;
}

.about-values {
    display: flex;
    gap: 24px;
    justify-content: center;
    margin-bottom: 48px;
    flex-wrap: wrap;
}

.value-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
}

.value-num {
    font-size: 2rem;
    font-weight: 800;
    background: var(--gradient-hero);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.value-text {
    font-size: 0.9375rem;
    color: var(--text-secondary);
    font-weight: 500;
}

/* ============================================================
   页脚
   ============================================================ */
.footer {
    border-top: 1px solid var(--border);
    padding: 60px 24px 40px;
}

.footer-content {
    max-width: var(--max-width);
    margin: 0 auto;
    text-align: center;
}

.footer-brand {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    font-size: 1.125rem;
    font-weight: 700;
    margin-bottom: 12px;
}

.footer-tagline {
    font-size: 0.875rem;
    color: var(--text-muted);
    margin-bottom: 24px;
}

.footer-links {
    display: flex;
    justify-content: center;
    gap: 24px;
    margin-bottom: 24px;
}

.footer-links a {
    font-size: 0.875rem;
    color: var(--text-secondary);
    transition: color var(--transition);
}

.footer-links a:hover {
    color: var(--primary-light);
}

.footer-copyright {
    font-size: 0.8125rem;
    color: var(--text-muted);
}

/* ============================================================
   滚动动画 (reveal)
   ============================================================ */
[data-reveal] {
    opacity: 0;
    transform: translateY(60px);
    transition: all 0.8s cubic-bezier(0.16, 1, 0.3, 1);
}

[data-reveal].revealed {
    opacity: 1;
    transform: translateY(0);
}

[data-reveal].revealed-left {
    opacity: 1;
    transform: translateX(0);
}

/* ============================================================
   响应式设计
   ============================================================ */

/* Tablet */
@media (max-width: 1023px) {
    .feature-block {
        grid-template-columns: 1fr;
        gap: 40px;
    }

    .feature-block.reverse {
        direction: ltr;
    }

    .feature-visual {
        order: -1;
    }

    .highlights-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .section {
        padding: 80px 24px;
    }
}

/* Mobile */
@media (max-width: 767px) {
    .nav-links {
        position: fixed;
        top: var(--nav-height);
        left: 0;
        right: 0;
        background: rgba(10, 10, 15, 0.95);
        backdrop-filter: blur(20px);
        -webkit-backdrop-filter: blur(20px);
        flex-direction: column;
        padding: 24px;
        gap: 16px;
        transform: translateY(-100%);
        opacity: 0;
        transition: all var(--transition);
        border-bottom: 1px solid var(--border);
    }

    .nav-links.open {
        transform: translateY(0);
        opacity: 1;
    }

    .nav-toggle {
        display: flex;
    }

    .hero-stats {
        flex-direction: column;
        gap: 24px;
    }

    .highlights-grid {
        grid-template-columns: 1fr;
    }

    .section {
        padding: 60px 20px;
    }

    .section-header {
        margin-bottom: 48px;
    }

    .hero-actions {
        flex-direction: column;
        align-items: center;
    }

    .about-values {
        gap: 16px;
    }

    .feature-block {
        gap: 24px;
        margin-bottom: 80px;
    }

    .code-window,
    .review-card,
    .test-card,
    .doc-card {
        max-width: 100%;
    }
}

/* Small Mobile */
@media (max-width: 420px) {
    .hero-title-line {
        font-size: 2rem;
    }

    .feature-title {
        font-size: 1.375rem;
    }

    .footer-links {
        flex-wrap: wrap;
    }
}
