{"content": "/* ============================================================
   Three.js 粒子系统 — 炫酷动态星空背景
   用于 Hero 区域
   ============================================================ */
(function() {
    'use strict';

    const canvas = document.getElementById('particleCanvas');
    if (!canvas) return;

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer({
        canvas: canvas,
        alpha: true,
        antialias: true
    });

    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));

    // ---- 创建粒子系统 ----
    const particlesCount = 2000;
    const positions = new Float32Array(particlesCount * 3);
    const colors = new Float32Array(particlesCount * 3);

    const color1 = new THREE.Color('#6366F1'); // 靛蓝
    const color2 = new THREE.Color('#06B6D4'); // 青色

    for (let i = 0; i < particlesCount * 3; i += 3) {
        // 分布在球体范围内
        const radius = 15 + Math.random() * 10;
        const theta = Math.random() * Math.PI * 2;
        const phi = Math.acos((Math.random() * 2) - 1);

        positions[i] = Math.sin(phi) * Math.cos(theta) * radius;
        positions[i + 1] = Math.sin(phi) * Math.sin(theta) * radius * 0.6;
        positions[i + 2] = Math.cos(phi) * radius;

        // 随机颜色（蓝紫渐变）
        const mixFactor = Math.random();
        const color = color1.clone().lerp(color2, mixFactor);
        colors[i] = color.r;
        colors[i + 1] = color.g;
        colors[i + 2] = color.b;
    }

    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

    const material = new THREE.PointsMaterial({
        size: 0.08,
        vertexColors: true,
        transparent: true,
        opacity: 0.8,
        blending: THREE.AdditiveBlending,
        sizeAttenuation: true
    });

    const particles = new THREE.Points(geometry, material);
    scene.add(particles);

    // ---- 连接线（邻近粒子之间）----
    const lineGeometry = new THREE.BufferGeometry();
    const linePositions = new Float32Array(particlesCount * 3);
    lineGeometry.setAttribute('position', new THREE.BufferAttribute(linePositions, 3));

    const lineMaterial = new THREE.LineBasicMaterial({
        color: '#6366F1',
        transparent: true,
        opacity: 0.05,
        blending: THREE.AdditiveBlending
    });

    const lines = new THREE.LineSegments(lineGeometry, lineMaterial);
    scene.add(lines);

    // ---- 鼠标交互 ----
    let mouseX = 0;
    let mouseY = 0;

    document.addEventListener('mousemove', (e) => {
        mouseX = (e.clientX / window.innerWidth) * 2 - 1;
        mouseY = -(e.clientY / window.innerHeight) * 2 + 1;
    });

    // ---- 窗口自适应 ----
    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });

    // ---- 动画循环 ----
    camera.position.z = 20;

    function animate() {
        requestAnimationFrame(animate);

        // 粒子缓慢旋转
        particles.rotation.x += 0.0003;
        particles.rotation.y += 0.0005;

        // 鼠标跟随
        particles.rotation.x += (mouseY * 0.02 - particles.rotation.x) * 0.01;
        particles.rotation.y += (mouseX * 0.02 - particles.rotation.y) * 0.01;

        renderer.render(scene, camera);
    }

    animate();
})();
