{"content": "/* ============================================================
   数字计数器动画
   当统计数字进入视口时，从 0 滚动到目标值
   ============================================================ */
(function() {
    'use strict';

    function initCounters() {
        const counters = document.querySelectorAll('[data-count]');
        if (!counters.length) return;

        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    const el = entry.target;
                    const target = parseInt(el.dataset.count, 10);
                    animateCounter(el, target);
                    observer.unobserve(el);
                }
            });
        }, { threshold: 0.5 });

        counters.forEach(counter => observer.observe(counter));
    }

    function animateCounter(el, target) {
        const duration = 2000; // ms
        const startTime = performance.now();
        const startValue = 0;

        function update(currentTime) {
            const elapsed = currentTime - startTime;
            const progress = Math.min(elapsed / duration, 1);

            // easeOutExpo
            const eased = progress === 1 ? 1 : 1 - Math.pow(2, -10 * progress);
            const current = Math.floor(startValue + (target - startValue) * eased);

            el.textContent = current;

            if (progress < 1) {
                requestAnimationFrame(update);
            } else {
                el.textContent = target;
            }
        }

        requestAnimationFrame(update);
    }

    // 页面加载完成后初始化
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initCounters);
    } else {
        initCounters();
    }
})();", "path": "D:\cncodetest\js\counters.js"}

{"content": "/* ============================================================
   GSAP 动画 + ScrollTrigger 滚动动画
   驱动页面中的高级动画效果
   ============================================================ */
(function() {
    'use strict';

    // 等待 GSAP 和 ScrollTrigger 加载
    function initAnimations() {
        if (typeof gsap === 'undefined' || typeof ScrollTrigger === 'undefined') {
            setTimeout(initAnimations, 200);
            return;
        }

        // 注册 ScrollTrigger
        gsap.registerPlugin(ScrollTrigger);

        // ---- 1. Hero 区域出场动画 ----
        const heroTl = gsap.timeline({ defaults: { ease: 'power3.out' } });

        heroTl
            .fromTo('.hero-badge',
                { opacity: 0, y: 30 },
                { opacity: 1, y: 0, duration: 0.8 }
            )
            .fromTo('.hero-title-line',
                { opacity: 0, y: 40 },
                { opacity: 1, y: 0, duration: 0.8, stagger: 0.2 },
                '-=0.4'
            )
            .fromTo('.hero-subtitle',
                { opacity: 0, y: 20 },
                { opacity: 1, y: 0, duration: 0.6 },
                '-=0.3'
            )
            .fromTo('.hero-actions',
                { opacity: 0, y: 20 },
                { opacity: 1, y: 0, duration: 0.6 },
                '-=0.2'
            )
            .fromTo('.hero-stats',
                { opacity: 0, y: 30 },
                { opacity: 1, y: 0, duration: 0.8 },
                '-=0.1'
            )
            .fromTo('.scroll-indicator',
                { opacity: 0 },
                { opacity: 1, duration: 0.6 },
                '-=0.4'
            );

        // ---- 2. 特性区块滚动动画 ----
        const featureBlocks = document.querySelectorAll('.feature-block');
        featureBlocks.forEach((block, i) => {
            const visual = block.querySelector('.feature-visual');
            const content = block.querySelector('.feature-content');

            const tl = gsap.timeline({
                scrollTrigger: {
                    trigger: block,
                    start: 'top 80%',
                    end: 'bottom 20%',
                    toggleActions: 'play none none reverse'
                }
            });

            tl.fromTo(visual,
                { opacity: 0, x: block.classList.contains('reverse') ? 80 : -80 },
                { opacity: 1, x: 0, duration: 0.8, ease: 'power3.out' }
            ).fromTo(content,
                { opacity: 0, x: block.classList.contains('reverse') ? -80 : 80 },
                { opacity: 1, x: 0, duration: 0.8, ease: 'power3.out' },
                '-=0.6'
            );
        });

        // ---- 3. 核心特色卡片交错出现 ----
        const cards = document.querySelectorAll('.highlight-card');
        cards.forEach((card, i) => {
            gsap.fromTo(card,
                { opacity: 0, y: 60 },
                {
                    opacity: 1, y: 0, duration: 0.7, delay: i * 0.1,
                    ease: 'power3.out',
                    scrollTrigger: {
                        trigger: card,
                        start: 'top 85%',
                        toggleActions: 'play none none reverse'
                    }
                }
            );
        });

        // ---- 4. 关于区域渐入 ----
        gsap.fromTo('.about-content',
            { opacity: 0, y: 40 },
            {
                opacity: 1, y: 0, duration: 0.8, ease: 'power3.out',
                scrollTrigger: {
                    trigger: '.about-content',
                    start: 'top 80%',
                    toggleActions: 'play none none reverse'
                }
            }
        );

        // ---- 5. 导航栏滚动效果（毛玻璃） ----
        ScrollTrigger.create({
            start: 'top -100px',
            onUpdate: (self) => {
                const navbar = document.getElementById('navbar');
                if (self.progress > 0) {
                    navbar.classList.add('scrolled');
                } else {
                    navbar.classList.remove('scrolled');
                }
            }
        });

        // ---- 6. 数字统计随滚动激活（配合 counters.js） ----
        // counters.js 已用 IntersectionObserver 处理
    }

    // 启动
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initAnimations);
    } else {
        initAnimations();
    }
})();", "path": "D:\cncodetest\js\animations.js"}

{"content": "/* ============================================================
   CN Codex 企业官网 — 主 JS
   导航控制、滚动渐入、响应式菜单
   ============================================================ */
(function() {
    'use strict';

    // ---- DOM 引用 ----
    const navbar = document.getElementById('navbar');
    const navToggle = document.getElementById('navToggle');
    const navLinks = document.getElementById('navLinks');
    const navLinkItems = document.querySelectorAll('.nav-link');

    // ---- 移动端菜单切换 ----
    if (navToggle) {
        navToggle.addEventListener('click', () => {
            navToggle.classList.toggle('open');
            navLinks.classList.toggle('open');
        });
    }

    // ---- 点击导航项后关闭菜单 ----
    navLinkItems.forEach(link => {
        link.addEventListener('click', () => {
            navToggle.classList.remove('open');
            navLinks.classList.remove('open');
        });
    });

    // ---- 滚动时高亮当前导航项 ----
    function updateActiveNav() {
        const scrollY = window.scrollY + 120; // 偏移补偿导航高度

        const sections = [
            { id: 'hero', link: document.querySelector('.nav-link[href="#hero"]') },
            { id: 'features', link: document.querySelector('.nav-link[href="#features"]') },
            { id: 'highlights', link: document.querySelector('.nav-link[href="#highlights"]') },
            { id: 'about', link: document.querySelector('.nav-link[href="#about"]') }
        ];

        let currentSection = sections[0];

        for (const section of sections) {
            const el = document.getElementById(section.id);
            if (el && el.offsetTop <= scrollY) {
                currentSection = section;
            }
        }

        navLinkItems.forEach(link => link.classList.remove('active'));
        if (currentSection.link) {
            currentSection.link.classList.add('active');
        }
    }

    // ---- 滚动渐入 (IntersectionObserver) ----
    function initRevealAnimations() {
        const revealElements = document.querySelectorAll('[data-reveal]');

        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('revealed');
                    observer.unobserve(entry.target);
                }
            });
        }, {
            threshold: 0.15,
            rootMargin: '0px 0px -50px 0px'
        });

        revealElements.forEach(el => observer.observe(el));
    }

    // ---- 导航滚动监听（去抖） ----
    let scrollTicking = false;

    function onScroll() {
        if (!scrollTicking) {
            requestAnimationFrame(() => {
                updateActiveNav();
                scrollTicking = false;
            });
            scrollTicking = true;
        }
    }

    // ---- 初始化 ----
    function init() {
        initRevealAnimations();
        updateActiveNav();
        window.addEventListener('scroll', onScroll, { passive: true });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();", "path": "D:\cncodetest\js\main.js"}

{"content": "<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>CN Codex 官网 — 测试报告</title>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body {
            font-family: 'Inter', system-ui, -apple-system, sans-serif;
            background: #0A0A0F;
            color: #E2E8F0;
            padding: 40px 24px;
        }
        .container { max-width: 900px; margin: 0 auto; }
        h1 {
            font-size: 2rem;
            background: linear-gradient(135deg, #6366F1, #06B6D4);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
            margin-bottom: 8px;
        }
        .subtitle { color: #94A3B8; margin-bottom: 40px; }
        .test-section {
            background: #1A1A2E;
            border: 1px solid rgba(99,102,241,0.2);
            border-radius: 16px;
            padding: 24px;
            margin-bottom: 24px;
        }
        .test-section h2 {
            font-size: 1.25rem;
            margin-bottom: 16px;
            display: flex;
            align-items: center;
            gap: 8px;
        }
        .test-item {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 12px 0;
            border-bottom: 1px solid rgba(255,255,255,0.05);
        }
        .test-item:last-child { border-bottom: none; }
        .test-name { font-size: 0.9375rem; }
        .test-detail { font-size: 0.8125rem; color: #94A3B8; margin-top: 2px; }
        .test-status {
            padding: 4px 12px;
            border-radius: 100px;
            font-size: 0.75rem;
            font-weight: 600;
        }
        .pass { background: rgba(34,197,94,0.15); color: #22C55E; }
        .fail { background: rgba(239,68,68,0.15); color: #EF4444; }
        .pending { background: rgba(245,158,11,0.15); color: #F59E0B; }
        .summary {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 16px;
            margin-bottom: 32px;
        }
        .summary-card {
            background: #1A1A2E;
            border: 1px solid rgba(99,102,241,0.2);
            border-radius: 12px;
            padding: 20px;
            text-align: center;
        }
        .summary-number {
            font-size: 2rem;
            font-weight: 800;
            background: linear-gradient(135deg, #6366F1, #06B6D4);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }
        .summary-label { font-size: 0.875rem; color: #94A3B8; margin-top: 4px; }
        .test-actions {
            display: flex;
            gap: 16px;
            margin-bottom: 40px;
            flex-wrap: wrap;
        }
        .test-btn {
            padding: 12px 24px;
            border-radius: 50px;
            border: none;
            font-family: inherit;
            font-size: 0.9375rem;
            font-weight: 600;
            cursor: pointer;
            transition: all 0.3s;
        }
        .test-btn.primary {
            background: linear-gradient(90deg, #6366F1, #8B5CF6);
            color: white;
        }
        .test-btn.primary:hover { transform: translateY(-2px); box-shadow: 0 4px 20px rgba(99,102,241,0.3); }
        .test-btn.outline {
