        .log-fail { color: #EF4444; }
        .log-info { color: #60A5FA; }
        @media (max-width: 600px) {
            .summary { grid-template-columns: 1fr; }
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>🧪 CN Codex 官网 — 自动测试</h1>
        <p class="subtitle">所有测试在浏览器中自动执行，验证网站功能和视觉完整性</p>

        <div class="summary" id="summary">
            <div class="summary-card">
                <div class="summary-number" id="totalCount">0</div>
                <div class="summary-label">总测试用例</div>
            </div>
            <div class="summary-card">
                <div class="summary-number" style="background: linear-gradient(135deg, #22C55E, #4ADE80); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text;" id="passCount">0</div>
                <div class="summary-label">通过</div>
            </div>
            <div class="summary-card">
                <div class="summary-number" style="color: #EF4444; -webkit-text-fill-color: #EF4444;" id="failCount">0</div>
                <div class="summary-label">失败</div>
            </div>
        </div>

        <div class="test-actions">
            <button class="test-btn primary" onclick="runAllTests()">▶ 运行所有测试</button>
            <button class="test-btn outline" onclick="clearLog()">清除日志</button>
        </div>

        <div id="testResults"></div>

        <h2 style="margin-top: 32px; margin-bottom: 12px;">📋 测试日志</h2>
        <div class="test-log" id="testLog">点击"运行所有测试"开始...</div>
    </div>

    <script>
        // ================================================================
        // CN Codex 官网测试套件
        // ================================================================

        const TestSuite = {
            tests: [],
            results: [],
            log: [],

            add(name, fn, detail = '') {
                this.tests.push({ name, fn, detail });
            },

            async runAll() {
                this.results = [];
                this.log = [];
                this.clearResults();
                this.logMsg('🧪 测试套件启动...', 'info');

                for (const test of this.tests) {
                    try {
                        const result = await test.fn();
                        const passed = result === true;
                        this.results.push({ name: test.name, passed, detail: test.detail, error: null });
                        if (passed) {
                            this.logMsg(`✅ 通过: ${test.name}`, 'pass');
                        } else {
                            this.logMsg(`❌ 失败: ${test.name} — ${result}`, 'fail');
                        }
                    } catch (err) {
                        this.results.push({ name: test.name, passed: false, detail: test.detail, error: err.message });
                        this.logMsg(`❌ 错误: ${test.name} — ${err.message}`, 'fail');
                    }
                }

                this.renderResults();
                this.renderSummary();

                const pass = this.results.filter(r => r.passed).length;
                const fail = this.results.filter(r => !r.passed).length;
                this.logMsg(`\n📊 测试完成: ${pass} 通过, ${fail} 失败 / ${this.results.length} 总用例`, 'info');
                return { pass, fail, total: this.results.length };
            },

            logMsg(msg, type = 'info') {
                this.log.push({ msg, type });
                const logEl = document.getElementById('testLog');
                const line = document.createElement('div');
                line.className = `log-${type}`;
                line.textContent = msg;
                logEl.appendChild(line);
                logEl.scrollTop = logEl.scrollHeight;
            },

            clearResults() {
                document.getElementById('testResults').innerHTML = '';
                document.getElementById('testLog').innerHTML = '';
                document.getElementById('totalCount').textContent = '0';
                document.getElementById('passCount').textContent = '0';
                document.getElementById('failCount').textContent = '0';
            },

            renderResults() {
                const container = document.getElementById('testResults');
