        // ================================================================
        // CN Codex 官网 — 自动化测试套件
        // 通过 iframe 加载主站进行 DOM 检测
        // ================================================================

        const TestSuite = {
            tests: [],
            results: [],
            log: [],

            add(name, fn, detail = '') {
