                        html += `<div class="test-item">
                            <div><div class="test-name">${item.name}</div>
                            ${item.error ? `<div class="test-detail">${item.error}</div>` : ''}</div>
                            <span class="test-status ${item.passed ? 'pass' : 'fail'}">${item.passed ? '通过' : '失败'}</span>
                        </div>`;
                    });
                    html += `</div>`;
                }
                container.innerHTML = html;
            },

            renderSummary() {
                const total = this.results.length;
                const pass = this.results.filter(r => r.passed).length;
                const fail = this.results.filter(r => !r.passed).length;
                document.getElementById('totalCount').textContent = total;
                document.getElementById('passCount').textContent = pass;
                document.getElementById('failCount').textContent = fail;
            }
        };

        // ================================================================
        // 定义测试用例（每个测试接收 iframe 的 document 对象）
        // ================================================================

        // ---- 1. 页面结构 ----
        TestSuite.add('页面存在导航栏', (doc) => {
            const nav = doc.querySelector('.navbar');
            return !!nav ? true : '导航栏元素未找到';
        }, '页面结构');

        TestSuite.add('导航链接为 4 个', (doc) => {
            const links = doc.querySelectorAll('.nav-link');
            return links.length >= 4 ? true : `导航链接数为 ${links.length}，不足 4 个`;
        }, '页面结构');

        TestSuite.add('页面存在 Hero 区域', (doc) => {
            const hero = doc.getElementById('hero');
            return !!hero ? true : 'Hero 区域未找到';
        }, '页面结构');

        TestSuite.add('页面存在功能区块', (doc) => {
            const features = doc.getElementById('features');
            return !!features ? true : '功能区块未找到';
        }, '页面结构');

        TestSuite.add('页面存在核心特色区块', (doc) => {
            const highlights = doc.getElementById('highlights');
            return !!highlights ? true : '核心特色区块未找到';
        }, '页面结构');

        TestSuite.add('页面存在关于区域', (doc) => {
            const about = doc.getElementById('about');
            return !!about ? true : '关于区域未找到';
        }, '页面结构');

        TestSuite.add('页面存在页脚', (doc) => {
            const footer = doc.querySelector('.footer');
            return !!footer ? true : '页脚未找到';
        }, '页面结构');

        TestSuite.add('页面标题正确', (doc) => {
            const title = doc.title;
            return title.includes('CN Codex') ? true : `标题为 "${title}"`;
        }, '页面结构');

        // ---- 2. 内容完整性 ----
        TestSuite.add('存在品牌标语 "AI 编程"', (doc) => {
